import {esc,icon,formatDate,formatTime} from './ui.js';
import {employeePickerField,setupEmployeePicker} from './employee-picker.js';

const root=document.querySelector('#briefing-link'),token=location.hash.slice(1),intro=root.querySelector('.intro').outerHTML;
let people=[],today='',stream=null,photo=null,preview='',pending=null,busy=false,closed=false,requestKey=crypto.randomUUID();
async function request(action,body){
  const response=await fetch(`/api/briefing-link/${action}`,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'omit',redirect:'error',body:JSON.stringify({...body,token}),signal:AbortSignal.timeout(action==='submit'?45000:25000)});
  let data;try{data=await response.json();}catch{throw new Error('Hasil pengiriman belum dapat dikonfirmasi. Coba kirim ulang.');}
  if(!response.ok){const error=new Error(data.error||'Permintaan belum berhasil.');error.status=response.status;throw error;}return data;
}
function stopCamera(){stream?.getTracks().forEach(track=>track.stop());stream=null;const video=root.querySelector('video');if(video)video.srcObject=null;const view=root.querySelector('.camera-view');if(view)view.hidden=true;}
function clearPhoto(){if(preview)URL.revokeObjectURL(preview);photo=null;preview='';}
function render(){
  stopCamera();clearPhoto();pending=null;busy=false;
  root.innerHTML=`${intro}<form id="briefing-form"><fieldset class="coaching-fields"><section class="step"><div class="step-title"><span class="step-number">1</span><h2>Pemberi briefing dan unit</h2></div><label class="field"><span>Tanggal briefing (WITA) *</span><input type="date" name="held_on" value="${esc(today)}" max="${esc(today)}" required></label><div data-person>${employeePickerField({label:'Nama lengkap pemberi briefing *',required:true,placeholder:'Ketik nama Anda…'})}</div><label class="field"><span>Bidang / unit</span><input data-unit-name readonly placeholder="Terisi setelah memilih nama"><input type="hidden" name="org_unit_id"></label><label class="field"><span>Jabatan</span><input data-job-title readonly placeholder="Terisi dari penempatan pegawai"></label><label class="field"><span>Bagian / urusan *</span><input name="section" required maxlength="200" placeholder="Contoh: Sumber Daya Manusia"></label><p class="hint">Bidang dan jabatan mengikuti penempatan pegawai pada tanggal briefing.</p></section><section class="step"><div class="step-title"><span class="step-number">2</span><h2>Hasil wewarah</h2></div><label class="field"><span>Pegawai yang tidak hadir *</span><textarea name="absent_notes" required maxlength="3000" placeholder="Tuliskan nama pegawai yang tidak hadir. Isi Nihil jika seluruhnya hadir."></textarea></label><label class="field"><span>Materi wewarah dan kendala (jika ada) *</span><textarea name="briefing_notes" required maxlength="10000" placeholder="Tuliskan arahan, prioritas pekerjaan, dan kendala yang disampaikan pagi ini."></textarea></label></section><section class="step"><div class="step-title"><span class="step-number">3</span><h2>Foto briefing</h2></div><p class="hint">Ambil satu foto langsung dari kamera. Pastikan kegiatan briefing terlihat jelas.</p><button type="button" class="button wide" data-camera>${icon('camera')}Buka kamera</button><div class="camera-view" hidden><video autoplay muted playsinline aria-label="Pratinjau kamera briefing"></video><div class="camera-actions"><button type="button" class="button primary" data-snap>Ambil foto</button><button type="button" class="button" data-camera-close>Tutup kamera</button></div></div><p class="status" role="status" data-camera-status></p><figure class="coaching-preview" hidden><img alt="Pratinjau foto briefing"><figcaption><button type="button" class="remove-photo" data-remove-photo>Hapus foto dan ambil ulang</button></figcaption></figure></section><div class="hidden-field" aria-hidden="true" inert><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div></fieldset><p class="form-error" role="alert"></p><button type="submit" class="button primary wide">${icon('check')}Kirim briefing</button><p class="submit-note">Periksa nama dan unit sebelum mengirim. Rekap hanya dapat dibaca melalui akun portal yang berhak.</p></form>`;
  const form=root.querySelector('form'),fields=form.querySelector('fieldset'),error=form.querySelector('.form-error'),send=form.querySelector('[type=submit]'),cameraStatus=form.querySelector('[data-camera-status]'),video=form.querySelector('video');
  function bindPicker(){setupEmployeePicker(form.querySelector('[data-person]'),people,{required:true,onSelect:person=>{form.querySelector('[name=org_unit_id]').value=person?.org_unit_id||'';form.querySelector('[data-unit-name]').value=person?.unit_name||'';form.querySelector('[data-job-title]').value=person?.job_title||'';}});}
  bindPicker();let contextVersion=0,loadingContext=false;
  form.querySelector('[name=held_on]').addEventListener('change',async event=>{
    if(busy)return;const version=++contextVersion;loadingContext=true;send.disabled=true;error.textContent='';
    form.querySelector('[name=org_unit_id]').value='';form.querySelector('[data-unit-name]').value='';form.querySelector('[data-job-title]').value='';
    try{const data=await request('context',{held_on:event.target.value});if(version!==contextVersion||!form.isConnected)return;people=data.employees;form.querySelector('[data-person]').innerHTML=employeePickerField({label:'Nama lengkap pemberi briefing *',required:true,placeholder:'Pilih kembali nama Anda…'});bindPicker();}
    catch(failure){if(version===contextVersion)error.textContent=failure.message;}
    finally{if(version===contextVersion){loadingContext=false;send.disabled=false;}}
  });
  form.querySelector('[data-camera]').addEventListener('click',async()=>{
    if(busy)return;const control=form.querySelector('[data-camera]');control.disabled=true;cameraStatus.textContent='Membuka kamera…';
    try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('Kamera tidak tersedia. Buka tautan ini pada browser HP melalui HTTPS.');stopCamera();const media=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:960}},audio:false});if(closed||busy||!form.isConnected){media.getTracks().forEach(track=>track.stop());return;}stream=media;video.srcObject=media;await video.play();form.querySelector('.camera-view').hidden=false;cameraStatus.textContent='Arahkan kamera ke kegiatan briefing.';}
    catch(failure){stopCamera();cameraStatus.textContent=failure.name==='NotAllowedError'?'Izinkan akses kamera pada pengaturan browser, lalu coba kembali.':failure.name==='NotFoundError'?'Kamera tidak ditemukan. Buka tautan ini pada HP yang memiliki kamera.':'Kamera belum dapat dibuka. Tutup aplikasi kamera lain lalu coba kembali.';}
    finally{if(form.isConnected)control.disabled=busy;}
  });
  form.querySelector('[data-camera-close]').addEventListener('click',stopCamera);
  form.querySelector('[data-snap]').addEventListener('click',async()=>{
    if(busy||!stream||!video.videoWidth){cameraStatus.textContent='Tunggu gambar kamera, lalu ambil foto.';return;}
    const control=form.querySelector('[data-snap]');control.disabled=true;
    try{const canvas=document.createElement('canvas'),scale=Math.min(1,1280/video.videoWidth,1280/video.videoHeight);canvas.width=Math.round(video.videoWidth*scale);canvas.height=Math.round(video.videoHeight*scale);canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.85));if(!blob||blob.size>10485760)throw new Error('Foto belum dapat disimpan. Ambil kembali.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('Foto belum dapat dibaca.'));reader.readAsDataURL(blob);});if(closed||busy||!form.isConnected)return;clearPhoto();photo={data,mime_type:'image/jpeg',captured_at:new Date().toISOString(),source:'CAMERA'};preview=URL.createObjectURL(blob);const figure=form.querySelector('figure');figure.querySelector('img').src=preview;figure.hidden=false;stopCamera();cameraStatus.textContent='Foto berhasil diambil.';}
    catch(failure){cameraStatus.textContent=failure.message;}finally{control.disabled=busy;}
  });
  form.querySelector('[data-remove-photo]').addEventListener('click',()=>{if(busy)return;clearPhoto();form.querySelector('figure').hidden=true;cameraStatus.textContent='Buka kamera untuk mengambil foto kembali.';});
  form.addEventListener('submit',async event=>{
    event.preventDefault();if(busy||loadingContext)return;error.textContent='';
    if(!pending){const data=Object.fromEntries(new FormData(form));if(!people.some(p=>p.id===data.employee_id&&!p.disabled)){error.textContent='Pilih nama Anda dari hasil pencarian.';return;}if(!photo){error.textContent='Ambil satu foto briefing dari kamera terlebih dahulu.';return;}pending={...data,photo:{...photo},idempotency_key:requestKey};}
    busy=true;fields.disabled=true;send.disabled=true;send.textContent='Mengirim briefing…';stopCamera();
    try{const result=await request('submit',pending);clearPhoto();pending=null;root.innerHTML=`<section class="message" role="status"><p class="eyebrow">Selesai</p><h1>Briefing berhasil dikirim</h1><p>Terima kasih. Wewarah Semeng tim Anda sudah tersimpan di SPH-Portal.</p><div class="receipt">${esc(result.reference)}</div><p class="hint">Diterima ${formatDate(result.received_at)} pukul ${formatTime(result.received_at)} WITA.</p><button type="button" class="button primary wide" data-new>Isi briefing berikutnya</button></section>`;root.querySelector('[data-new]').addEventListener('click',()=>{requestKey=crypto.randomUUID();start();});window.scrollTo({top:0,behavior:'smooth'});}
    catch(failure){busy=false;send.disabled=false;if([400,413,415,422].includes(failure.status)){pending=null;fields.disabled=false;send.innerHTML=`${icon('check')}Kirim briefing`;error.textContent=failure.message;}else{send.textContent='Kirim ulang';error.textContent=(['TimeoutError','TypeError'].includes(failure.name)?'Pengiriman belum dapat dikonfirmasi.':failure.message)+' Tekan Kirim ulang untuk mengirim jawaban yang sama.';}}
  });
}
async function start(){
  if(!/^[a-f0-9]{64}$/.test(token)){root.innerHTML='<section class="message"><h1>Tautan belum lengkap</h1><p>Buka tautan lengkap melalui menu Briefing Pagi di portal atau tautan yang dibagikan SDM.</p></section>';return;}
  try{const data=await request('context',{});people=data.employees;today=data.today;if(!people.some(p=>!p.disabled))throw new Error('Pegawai dengan penempatan aktif belum tersedia. Hubungi SDM.');render();}
  catch(failure){root.innerHTML=`<section class="message"><h1>Formulir belum dapat dibuka</h1><p>${esc(failure.message)}</p><button type="button" class="button primary wide" data-retry>Coba buka kembali</button></section>`;root.querySelector('[data-retry]').addEventListener('click',start);}
}
window.addEventListener('pagehide',()=>{closed=true;stopCamera();});window.addEventListener('pageshow',()=>{closed=false;});window.addEventListener('hashchange',()=>location.reload());start();
